from pathlib import Path

p = Path('project/src/main/java/com/mcmoddev/golems/test/BedrockNaturalAiGameTest.java')
s = p.read_text()

old_import = 'import net.minecraft.world.entity.EntityType;\n'
new_import = '''import net.minecraft.world.entity.EntityType;\nimport net.minecraft.world.entity.Mob;\nimport net.minecraft.world.entity.ai.goal.GoalSelector;\nimport net.minecraft.world.entity.ai.goal.WrappedGoal;\n'''
if old_import not in s:
    raise SystemExit('EntityType import marker missing for goal debug')
s = s.replace(old_import, new_import, 1)

old_class = '''public final class BedrockNaturalAiGameTest implements FabricGameTest {\n    @GameTest'''
new_class = '''public final class BedrockNaturalAiGameTest implements FabricGameTest {\n    private static GoalSelector getTargetSelector(final Mob mob) throws ReflectiveOperationException {\n        final java.lang.reflect.Field f = Mob.class.getDeclaredField("targetSelector");\n        f.setAccessible(true);\n        return (GoalSelector) f.get(mob);\n    }\n\n    private static String describeTargetGoals(final Mob mob) {\n        try {\n            final GoalSelector selector = getTargetSelector(mob);\n            final String goals = selector.getAvailableGoals().stream()\n                    .map(w -> {\n                        String canUse;\n                        try {\n                            canUse = Boolean.toString(w.getGoal().canUse());\n                        } catch (Throwable t) {\n                            canUse = "error:" + t.getClass().getSimpleName();\n                        }\n                        return w.getGoal().getClass().getSimpleName()\n                                + "[running=" + w.isRunning() + ",canUse=" + canUse + "]";\n                    })\n                    .sorted()\n                    .reduce((a, b) -> a + "," + b)\n                    .orElse("<none>");\n\n            final StringBuilder internals = new StringBuilder();\n            for (java.lang.reflect.Field field : GoalSelector.class.getDeclaredFields()) {\n                field.setAccessible(true);\n                final Object value = field.get(selector);\n                if (value instanceof java.util.Map<?, ?> map) {\n                    if (internals.length() > 0) internals.append('|');\n                    internals.append(field.getName()).append('=');\n                    if (map.isEmpty()) {\n                        internals.append("{}");\n                    } else {\n                        boolean first = true;\n                        for (java.util.Map.Entry<?, ?> entry : map.entrySet()) {\n                            if (!first) internals.append(',');\n                            first = false;\n                            internals.append(entry.getKey()).append("->");\n                            final Object v = entry.getValue();\n                            if (v instanceof WrappedGoal w) {\n                                internals.append(w.getGoal().getClass().getSimpleName())\n                                        .append("[running=").append(w.isRunning()).append(']');\n                            } else {\n                                internals.append(String.valueOf(v));\n                            }\n                        }\n                    }\n                } else if (value instanceof java.util.Set<?> set && field.getName().toLowerCase().contains("disable")) {\n                    if (internals.length() > 0) internals.append('|');\n                    internals.append(field.getName()).append('=').append(set);\n                }\n            }\n            return goals + ";selectorInternals=" + internals;\n        } catch (ReflectiveOperationException e) {\n            return "<reflection-failed:" + e.getClass().getSimpleName() + ":" + e.getMessage() + ">";\n        }\n    }\n\n    @GameTest'''
if old_class not in s:
    raise SystemExit('GameTest class marker missing for goal debug')
s = s.replace(old_class, new_class, 1)

old_failure = '''                        "Bedrock failed proactive hostile-mob reacquisition after player retaliation; currentTarget="\n                                + bedrock.getTarget() + ", lastHurt=" + bedrock.getLastHurtByMob());'''
new_failure = '''                        "Bedrock failed proactive hostile-mob reacquisition after player retaliation; currentTarget="\n                                + bedrock.getTarget() + ", lastHurt=" + bedrock.getLastHurtByMob()\n                                + ", followRange=" + bedrock.getAttributeValue(Attributes.FOLLOW_RANGE)\n                                + ", distanceToProbe=" + bedrock.distanceTo(bedrockZombie)\n                                + ", bedrockGoals=" + describeTargetGoals(bedrock)\n                                + ", vanillaGoals=" + describeTargetGoals(vanilla));'''
if old_failure not in s:
    raise SystemExit('Final Bedrock failure marker missing for goal debug')
s = s.replace(old_failure, new_failure, 1)

p.write_text(s)
print('Added target-goal canUse and selector-lock diagnostics to Bedrock AI GameTest.')
